        public static bool byteInRange(Tsonic.CSharp.Node.Buffer bytes, int index, int minimum, int maximum)
        {
            if (index >= bytes.length)
            {
                return false;
            }
            int @byte = bytes.readUInt8(index);
            return @byte >= minimum && @byte <= maximum;
        }
        public static bool isValidUtf8(Tsonic.CSharp.Node.Buffer bytes)
        {
            int index = 0;
            while (index < bytes.length)
            {
                int first = bytes.readUInt8(index);
                if (first <= 127)
                {
                    index++;
                    continue;
                }
                if (first >= 194 && first <= 223)
                {
                    if (!byteInRange(bytes, index + 1, 128, 191))
                    {
                        return false;
                    }
                    index += 2;
                    continue;
                }
                if (first == 224)
                {
                    if (!byteInRange(bytes, index + 1, 160, 191) || !byteInRange(bytes, index + 2, 128, 191))
                    {
                        return false;
                    }
                    index += 3;
                    continue;
                }
                if ((first >= 225 && first <= 236) || (first >= 238 && first <= 239))
                {
                    if (!byteInRange(bytes, index + 1, 128, 191) || !byteInRange(bytes, index + 2, 128, 191))
                    {
                        return false;
                    }
                    index += 3;
                    continue;
                }
                if (first == 237)
                {
                    if (!byteInRange(bytes, index + 1, 128, 159) || !byteInRange(bytes, index + 2, 128, 191))
                    {
                        return false;
                    }
                    index += 3;
                    continue;
                }
                if (first == 240)
                {
                    if (!byteInRange(bytes, index + 1, 144, 191) || !byteInRange(bytes, index + 2, 128, 191) || !byteInRange(bytes, index + 3, 128, 191))
                    {
                        return false;
                    }
                    index += 4;
                    continue;
                }
                if (first >= 241 && first <= 243)
                {
                    if (!byteInRange(bytes, index + 1, 128, 191) || !byteInRange(bytes, index + 2, 128, 191) || !byteInRange(bytes, index + 3, 128, 191))
                    {
                        return false;
                    }
                    index += 4;
                    continue;
                }
                if (first == 244)
                {
                    if (!byteInRange(bytes, index + 1, 128, 143) || !byteInRange(bytes, index + 2, 128, 191) || !byteInRange(bytes, index + 3, 128, 191))
                    {
                        return false;
                    }
                    index += 4;
                    continue;
                }
                return false;
            }
            return true;
        }
        public static string readResourceText(Resource resource, string operation)
        {
            string? text = resource.text;
            if (text is not null)
            {
                return text;
            }
            if (!isValidUtf8(resource.bytes))
            {
                throw Node_modules_Tsumo_engine_src_diagnostics.createTsumoError("TSUMO_RESOURCE_TEXT_ENCODING_INVALID", $"{operation} requires a UTF-8 resource", resource.sourcePath);
            }
            return resource.bytes.toString("utf8");
        }
